package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType.getGenericSignature
 */
public class ReferenceType_getGenericSignature_TriageGen1Test {

    /**
     * Test the normal flow of getGenericSignature.
     * It verifies that:
     * 1. _classSignature is called (simulated via the class signature being present).
     * 2. '<' is appended.
     * 3. The referenced type's getGenericSignature is called.
     * 4. ';' is appended.
     */
    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        Class<?> clazz = String.class;
        JavaType mockReferencedType = mock(JavaType.class);

        // We use the static factory method to create the instance
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("Prefix:");

        // Mock the behavior of the referenced type's getGenericSignature
        // When called, it should append "TypeSig" to the builder and return it
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder argument = invocation.getArgument(0);
            argument.append("TypeSig");
            return argument;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected sequence:
        // 1. _classSignature (appends class name: java.lang.String)
        // 2. append('<')
        // 3. mockReferencedType.getGenericSignature (appends "TypeSig")
        // 4. append(';')
        // Result: "Prefix:java.lang.String<TypeSig;"

        String expected = "Prefix:java.lang.String<TypeSig;";
        assertEquals(expected, result.toString());
    }

    /**
     * Test with an empty StringBuilder to ensure no prefix issues.
     */
    @Test
    public void testGetGenericSignature_EmptyBuilder() {
        // Arrange
        Class<?> clazz = Integer.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder();

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder argument = invocation.getArgument(0);
            argument.append("IntSig");
            return argument;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected: "java.lang.Integer<IntSig;"
        String expected = "java.lang.Integer<IntSig;";
        assertEquals(expected, result.toString());
    }

    /**
     * Test behavior when the referenced type returns a different StringBuilder instance.
     * (Though in standard Jackson implementation, it usually returns the same one).
     */
    @Test
    public void testGetGenericSignature_DifferentStringBuilderReturned() {
        // Arrange
        Class<?> clazz = Object.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("Start");
        StringBuilder newSb = new StringBuilder("New");

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenReturn(newSb);

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // 1. sb gets class signature: "Startjava.lang.Object"
        // 2. sb gets '<': "Startjava.lang.Object<"
        // 3. mockReferencedType returns newSb
        // 4. newSb gets ';': "New;"
        String expected = "New;";
        assertEquals(expected, result.toString());
    }
}
